toolScript:
// Tab Switching
        function switchTab(tab) {
            ['sleep', 'bp', 'breath', 'navy'].forEach(t => {
                const mod = document.getElementById('module-' + t);
                const btn = document.getElementById('tab-btn-' + t);
                if (mod) mod.classList.toggle('hidden', t !== tab);
                if (btn) {
                    if (t === tab) {
                        btn.className = 'flex-1 min-w-[120px] py-2.5 px-3 rounded-xl text-xs font-bold transition-all shadow-sm bg-white text-slate-900 border border-slate-200';
                    } else {
                        btn.className = 'flex-1 min-w-[120px] py-2.5 px-3 rounded-xl text-xs font-bold transition-all text-slate-600 hover:text-slate-900';
                    }
                }
            });
        }

        // 1. Sleep Debt Calculation
        function calculateSleepDebt() {
            const target = parseFloat(document.getElementById('sleep-target')?.value) || 8.0;
            const avg = parseFloat(document.getElementById('sleep-avg')?.value) || 6.5;
            const diffPerNight = target - avg;
            const totalDeficit = Math.max(0, diffPerNight * 7);

            const defEl = document.getElementById('sleep-deficit-val');
            const barEl = document.getElementById('sleep-progress-bar');
            const noteEl = document.getElementById('sleep-recommendation');

            if (defEl) defEl.innerText = totalDeficit.toFixed(1) + ' Hours';
            if (barEl) {
                const pct = Math.min(100, Math.max(5, (totalDeficit / 20) * 100));
                barEl.style.width = pct + '%';
                barEl.className = totalDeficit > 10 ? 'bg-rose-500 h-full' : totalDeficit > 4 ? 'bg-amber-500 h-full' : 'bg-emerald-500 h-full';
            }
            if (noteEl) {
                if (totalDeficit <= 1.0) {
                    noteEl.innerText = 'Excellent sleep baseline. Your cumulative debt is negligible; cognitive alertness is operating near biological peak.';
                } else if (totalDeficit <= 6.0) {
                    noteEl.innerText = 'Moderate sleep debt (' + totalDeficit.toFixed(1) + ' hrs). Add 30-45 minutes per night over the next 3 days to recover.';
                } else {
                    noteEl.innerText = 'Elevated sleep debt (' + totalDeficit.toFixed(1) + ' hrs). Neurocognitive vigilance is compromised. Aim for an extra 60-90 minutes of sleep across 4 nights.';
                }
            }
        }

        // 2. Blood Pressure & MAP Calculation
        function calculateBP() {
            const sbp = parseFloat(document.getElementById('bp-sbp')?.value) || 120;
            const dbp = parseFloat(document.getElementById('bp-dbp')?.value) || 80;

            const map = dbp + (sbp - dbp) / 3;
            const pulse = sbp - dbp;

            const mapEl = document.getElementById('bp-map-val');
            const pulseEl = document.getElementById('bp-pulse-val');
            const badgeEl = document.getElementById('bp-tier-badge');
            const noteEl = document.getElementById('bp-clinical-note');

            if (mapEl) mapEl.innerText = map.toFixed(1) + ' mmHg';
            if (pulseEl) pulseEl.innerText = pulse.toFixed(0) + ' mmHg';

            let tier = 'Normal', badgeClass = 'bg-emerald-100 text-emerald-800', note = '';

            if (sbp >= 180 || dbp >= 120) {
                tier = 'Hypertensive Crisis';
                badgeClass = 'bg-rose-600 text-white';
                note = 'Emergency threshold. Seek immediate medical evaluation if accompanied by chest pain, shortness of breath, or numbness.';
            } else if (sbp >= 140 || dbp >= 90) {
                tier = 'Hypertension Stage 2';
                badgeClass = 'bg-rose-100 text-rose-800';
                note = 'Stage 2 hypertension range under AHA guidelines. Consistent readings require physician consultation.';
            } else if (sbp >= 130 || dbp >= 80) {
                tier = 'Hypertension Stage 1';
                badgeClass = 'bg-amber-100 text-amber-800';
                note = 'Stage 1 hypertension range. Lifestyle modifications, sodium moderation, and aerobic exercise are recommended.';
            } else if (sbp >= 120 && dbp < 80) {
                tier = 'Elevated';
                badgeClass = 'bg-amber-50 text-amber-700 border border-amber-200';
                note = 'Elevated systolic pressure with normal diastolic baseline. Monitor across multiple morning readings.';
            } else {
                tier = 'Normal';
                badgeClass = 'bg-emerald-100 text-emerald-800';
                note = 'Optimal perfusion pressure. MAP is within the healthy organ homeostasis window (70-100 mmHg).';
            }

            if (badgeEl) {
                badgeEl.innerText = tier;
                badgeEl.className = 'px-3 py-1 rounded-full text-xs font-black uppercase ' + badgeClass;
            }
            if (noteEl) noteEl.innerText = note;
        }

        // 3. Resonant Breathing Pacer
        let breathInterval = null;
        let isBreathing = false;
        let breathPhase = 'inhale'; // inhale or exhale

        function toggleBreathing() {
            if (isBreathing) {
                resetBreathing();
            } else {
                startBreathing();
            }
        }

        function startBreathing() {
            isBreathing = true;
            const btn = document.getElementById('btn-breath-toggle');
            if (btn) {
                btn.innerText = 'Pause Pacer';
                btn.className = 'px-8 py-3 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded-xl transition text-xs uppercase tracking-widest shadow-md';
            }
            runBreathCycle();
        }

        function runBreathCycle() {
            const circle = document.getElementById('breath-circle');
            const inst = document.getElementById('breath-instruction');
            const sec = document.getElementById('breath-seconds');

            if (breathPhase === 'inhale') {
                if (circle) circle.className = 'w-44 h-44 rounded-full border-4 border-teal-500 bg-teal-100 flex flex-col items-center justify-center transition-all duration-[5500ms] ease-in-out transform scale-125 shadow-2xl';
                if (inst) inst.innerText = 'Inhale';
                if (sec) sec.innerText = '5.5s';
                breathPhase = 'exhale';
            } else {
                if (circle) circle.className = 'w-44 h-44 rounded-full border-4 border-teal-500 bg-teal-50 flex flex-col items-center justify-center transition-all duration-[5500ms] ease-in-out transform scale-90 shadow-md';
                if (inst) inst.innerText = 'Exhale';
                if (sec) sec.innerText = '5.5s';
                breathPhase = 'inhale';
            }

            breathInterval = setTimeout(() => {
                if (isBreathing) runBreathCycle();
            }, 5500);
        }

        function resetBreathing() {
            isBreathing = false;
            clearTimeout(breathInterval);
            breathInterval = null;
            breathPhase = 'inhale';
            const btn = document.getElementById('btn-breath-toggle');
            const circle = document.getElementById('breath-circle');
            const inst = document.getElementById('breath-instruction');
            const sec = document.getElementById('breath-seconds');

            if (btn) {
                btn.innerText = 'Start Coherence Session';
                btn.className = 'px-8 py-3 bg-teal-600 hover:bg-teal-500 text-white font-bold rounded-xl transition text-xs uppercase tracking-widest shadow-md';
            }
            if (circle) circle.className = 'w-44 h-44 rounded-full border-4 border-teal-500 bg-teal-50 flex flex-col items-center justify-center transition-all duration-300 transform scale-100 shadow-lg';
            if (inst) inst.innerText = 'Ready';
            if (sec) sec.innerText = '5.5s';
        }

        // 4. US Navy Body Fat Calculation
        function updateNavyForm() {
            const isFemale = document.querySelector('input[name="navy-gender"]:checked')?.value === 'female';
            const hipCont = document.getElementById('navy-hip-container');
            if (hipCont) hipCont.classList.toggle('hidden', !isFemale);
        }

        function calculateNavy() {
            const gender = document.querySelector('input[name="navy-gender"]:checked')?.value || 'male';
            const height = parseFloat(document.getElementById('navy-height')?.value) || 178;
            const neck = parseFloat(document.getElementById('navy-neck')?.value) || 38;
            const waist = parseFloat(document.getElementById('navy-waist')?.value) || 84;
            const hip = parseFloat(document.getElementById('navy-hip')?.value) || 96;

            let fat = 15;
            if (gender === 'male') {
                if (waist > neck) {
                    fat = 495 / (1.0324 - 0.19077 * Math.log10(waist - neck) + 0.15456 * Math.log10(height)) - 450;
                }
            } else {
                if ((waist + hip) > neck) {
                    fat = 495 / (1.29579 - 0.35004 * Math.log10(waist + hip - neck) + 0.22100 * Math.log10(height)) - 450;
                }
            }
            fat = Math.max(3, Math.min(55, fat));

            const fatEl = document.getElementById('navy-fat-val');
            const badgeEl = document.getElementById('navy-category-badge');

            if (fatEl) fatEl.innerText = fat.toFixed(1) + '%';
            if (badgeEl) {
                let cat = 'Fitness Baseline', cls = 'bg-emerald-100 text-emerald-800';
                if (gender === 'male') {
                    if (fat < 6) { cat = 'Essential Fat'; cls = 'bg-amber-100 text-amber-800'; }
                    else if (fat <= 13) { cat = 'Athletes'; cls = 'bg-emerald-100 text-emerald-800'; }
                    else if (fat <= 17) { cat = 'Fitness Baseline'; cls = 'bg-teal-100 text-teal-800'; }
                    else if (fat <= 24) { cat = 'Acceptable'; cls = 'bg-slate-100 text-slate-800'; }
                    else { cat = 'Elevated Adiposity'; cls = 'bg-rose-100 text-rose-800'; }
                } else {
                    if (fat < 14) { cat = 'Essential Fat'; cls = 'bg-amber-100 text-amber-800'; }
                    else if (fat <= 20) { cat = 'Athletes'; cls = 'bg-emerald-100 text-emerald-800'; }
                    else if (fat <= 24) { cat = 'Fitness Baseline'; cls = 'bg-teal-100 text-teal-800'; }
                    else if (fat <= 31) { cat = 'Acceptable'; cls = 'bg-slate-100 text-slate-800'; }
                    else { cat = 'Elevated Adiposity'; cls = 'bg-rose-100 text-rose-800'; }
                }
                badgeEl.innerText = cat;
                badgeEl.className = 'px-2.5 py-0.5 rounded-full text-xs font-black uppercase ' + cls;
            }
        }

        // Copy Scorecard
        function copyHealthReport() {
            const sleepDeficit = document.getElementById('sleep-deficit-val')?.innerText || 'N/A';
            const bpTier = document.getElementById('bp-tier-badge')?.innerText || 'N/A';
            const map = document.getElementById('bp-map-val')?.innerText || 'N/A';
            const bodyFat = document.getElementById('navy-fat-val')?.innerText || 'N/A';

            const report = "=== BIOMETRIC & PHYSIOLOGICAL SCORECARD ===\n" +
                "Sleep Debt (7-Day Cumulative): " + sleepDeficit + "\n" +
                "Mean Arterial Pressure (MAP): " + map + "\n" +
                "AHA Blood Pressure Status: " + bpTier + "\n" +
                "US Navy Body Fat Estimate: " + bodyFat + "\n" +
                "Privacy Audit: 100% Client-Side Local Computation\n" +
                "Generated via ToolkitGen: https://toolkitgen.com/tool/health_metrics_dashboard";

            if (navigator.clipboard) {
                navigator.clipboard.writeText(report).then(() => {
                    const btn = document.getElementById('btn-copy-report');
                    if (btn) {
                        const old = btn.innerHTML;
                        btn.innerHTML = 'Scorecard Copied!';
                        setTimeout(() => btn.innerHTML = old, 1500);
                    }
                }).catch(() => prompt('Copy your biometric report:', report));
            } else {
                prompt('Copy your biometric report:', report);
            }
        }

        // Initialize on load
        window.addEventListener('DOMContentLoaded', () => {
            calculateSleepDebt();
            calculateBP();
            calculateNavy();
        });
